function validate([n, p, banned, k]) {
  if (!Number.isInteger(n) || n < 1 || n > 100000) return 'n is between 1 and 100000.';
  if (!Number.isInteger(p) || p < 0 || p >= n) return 'p is an index from 0 to n - 1.';
  if (!Number.isInteger(k) || k < 1 || k > n) return 'k is between 1 and n.';
  if (!Array.isArray(banned) || banned.length > n - 1) return 'banned holds at most n - 1 values.';
  const seen = new Set();
  for (const position of banned) {
    if (!Number.isInteger(position) || position < 0 || position >= n) return 'Each banned value is an index from 0 to n - 1.';
    if (position === p) return 'p itself cannot be banned.';
    if (seen.has(position)) return 'The values in banned are all different.';
    seen.add(position);
  }
  return null;
}

