function minReverseOperations(n, p, banned, k) {
  const answer = new Array(n).fill(-1);
  const nextFree = Array.from({ length: n + 2 }, (_, index) => index);
  const find = (index) => {
    while (nextFree[index] !== index) {
      nextFree[index] = nextFree[nextFree[index]];
      index = nextFree[index];
    }
    return index;
  };
  for (const position of banned) {
    nextFree[position] = position + 2;
  }
  nextFree[p] = p + 2;
  answer[p] = 0;
  const queue = [p];
  for (let head = 0; head < queue.length; head++) {
    const current = queue[head];
    const low = Math.max(current - k + 1, k - 1 - current);
    const high = Math.min(current + k - 1, 2 * n - k - 1 - current);
    for (let next = find(low); next <= high; next = find(next)) {
      answer[next] = answer[current] + 1;
      nextFree[next] = next + 2;
      queue.push(next);
    }
  }
  return answer;
}

