function minReverseOperations(n, p, banned, k) {
  // Level-by-level search that really reverses every window of a copy of the array.
  const blocked = new Set(banned);
  const answer = new Array(n).fill(-1);
  answer[p] = 0;
  let frontier = [p];
  for (let moves = 1; frontier.length > 0; moves++) {
    const upcoming = [];
    for (const at of frontier) {
      for (let start = 0; start + k <= n; start++) {
        const arr = new Array(n).fill(0);
        arr[at] = 1;
        const flipped = arr.slice(start, start + k).reverse();
        arr.splice(start, k, ...flipped);
        const where = arr.indexOf(1);
        if (blocked.has(where) || answer[where] !== -1) continue;
        answer[where] = moves;
        upcoming.push(where);
      }
    }
    frontier = upcoming;
  }
  return answer;
}

