function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(1500, 2000) : int(1, 10);
  const p = int(0, n - 1);
  const k = rand() < 0.15 ? n : int(1, n);
  let density;
  if (size === 'large') density = rand() < 0.3 ? 0 : rand() * 0.2;
  else density = rand() < 0.2 ? 0 : rand() * 0.5;
  const banned = [];
  for (let i = 0; i < n; i++) {
    if (i !== p && rand() < density) banned.push(i);
  }
  // banned does not have to be sorted, so shuffle it.
  for (let i = banned.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [banned[i], banned[j]] = [banned[j], banned[i]];
  }
  return [n, p, banned, k];
}
